mapper.update:
CREATE INDEX ${tableName}_IDX1 ON ${tableName} (MSG_STATUS, REQ_CH, TRAFFIC_TYPE, REQ_DATE);
CREATE INDEX ${tableName}_IDX2 ON ${tableName} (PHONE);
CREATE INDEX ${tableName}_IDX3 ON ${tableName} (DONE_CODE, REQ_DATE);

UPDATE ${tableName}
SET
    MSG_STATUS = CASE WHEN MSG_STATUS = 'complete' THEN MSG_STATUS ELSE #{parameter.messageStatus} END
    , REQ_CH = #{parameter.requestChannel}
    , ROUTE_INFO = #{parameter.routeId}
    , SENT_DATE = FROM_UNIXTIME(UNIX_TIMESTAMP(#{parameter.sentDate}))
    , DONE_CH = #{parameter.doneChannel}
    , DONE_PRODUCT = #{parameter.doneProduct}
    , DONE_DATE = FROM_UNIXTIME(UNIX_TIMESTAMP(#{parameter.doneDate}))
    , DONE_CODE = #{parameter.doneCode}
    , DONE_CODE_DESC = #{parameter.doneCodeDescription}
    , DONE_FB_DETAIL = #{parameter.doneFallbackDetail}
    , DONE_TELCO = #{parameter.doneTelco}
WHERE
    CLIENT_KEY IS NULL
    CLIENT_KEY = #{parameter.key}

DELETE FROM ${tableName}
WHERE
    CLIENT_KEY IS NULL
    CLIENT_KEY = #{parameter.key}
